PRAGMA foreign_keys = ON;
CREATE TABLE customers (customer_id INTEGER PRIMARY KEY, customer_name TEXT NOT NULL, city TEXT NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)));
INSERT INTO customers VALUES (1,'Asha','Hyderabad',1),(2,'Bilal','Vijayawada',1),(3,'Chitra','Hyderabad',0),(4,'Dinesh','Chennai',1),(5,'Farah','Mumbai',1),(6,'Gopal','Hyderabad',1);
CREATE TABLE products (product_id INTEGER PRIMARY KEY, product_name TEXT NOT NULL, category TEXT NOT NULL, price REAL NOT NULL CHECK(price>=0), stock_qty INTEGER NOT NULL CHECK(stock_qty>=0), discontinued INTEGER NOT NULL CHECK(discontinued IN (0,1)));
INSERT INTO products VALUES (1,'USB Cable','Accessories',250,20,0),(2,'Phone Case','Accessories',400,12,0),(3,'Notebook','Stationery',60,50,0),(4,'Pen','Stationery',10,100,0),(5,'Old Charger','Accessories',150,0,1),(6,'Mouse','Electronics',700,8,0),(7,'Keyboard','Electronics',1200,5,0);
CREATE TABLE orders (order_id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES customers(customer_id), order_date TEXT NOT NULL, status TEXT NOT NULL, total_amount REAL NOT NULL);
INSERT INTO orders VALUES (1,1,'2026-11-01','paid',560),(2,1,'2026-11-03','paid',180),(3,2,'2026-11-05','pending',400),(4,3,'2026-11-07','paid',70),(5,4,'2026-11-08','cancelled',0),(6,5,'2026-11-09','paid',1200);
CREATE TABLE order_items (order_item_id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(order_id), product_id INTEGER NOT NULL REFERENCES products(product_id), quantity INTEGER NOT NULL CHECK(quantity>0), unit_price REAL NOT NULL);
